"""Build Colab-ready notebooks from the Jupytext scripts.

Writes one .ipynb per notebook script into OUT_DIR, each with a first cell
that clones this repo (so datasets are available) and moves into the
notebook's folder, plus an index.ipynb linking to them all. The GitHub Action
in .github/workflows/colab.yml publishes OUT_DIR to the `colab` branch.

Usage: python .github/scripts/build_colab.py OUT_DIR
"""

import sys
from pathlib import Path

import jupytext
from nbformat.v4 import new_code_cell, new_markdown_cell, new_notebook

REPO = "cubsai/notebooks"
BRANCH = "colab"
COLAB = f"https://colab.research.google.com/github/{REPO}/blob/{BRANCH}"


def notebook_scripts(root: Path):
    """Notebook scripts: .py files in module folders, outside outputs/."""
    for path in sorted(root.glob("*/**/*.py")):
        parts = path.relative_to(root).parts
        if any(p.startswith(".") or p in ("outputs", ".ipynb_checkpoints") for p in parts):
            continue
        yield path


def setup_cells(folder: str):
    return [
        new_markdown_cell(
            "**Running in Colab:** run the next cell first. It downloads the "
            f"[{REPO}](https://github.com/{REPO}) repo, so the datasets are "
            "available, and moves into this notebook's folder."
        ),
        new_code_cell(
            "import os\n"
            "if not os.path.exists('/content/notebooks'):\n"
            f"    !git clone --depth 1 https://github.com/{REPO}.git /content/notebooks\n"
            f"%cd /content/notebooks/{folder}"
        ),
    ]


def main(out_dir: str) -> None:
    root = Path(".")
    out = Path(out_dir)
    links = []
    for script in notebook_scripts(root):
        rel = script.relative_to(root).with_suffix(".ipynb")
        nb = jupytext.read(script)
        nb.cells = setup_cells(str(rel.parent)) + nb.cells
        nb.metadata = {"kernelspec": {"name": "python3", "display_name": "Python 3"}}
        target = out / rel
        target.parent.mkdir(parents=True, exist_ok=True)
        jupytext.write(nb, target)
        links.append(f"- [{rel.with_suffix('')}]({COLAB}/{rel.as_posix()})")

    index = new_notebook(
        cells=[
            new_markdown_cell(
                "# Notebooks for Colab\n\n"
                f"Built automatically from [{REPO}](https://github.com/{REPO}). "
                "Open a notebook below; changes you make are saved only if you "
                "save a copy (File → Save a copy in Drive).\n\n" + "\n".join(links)
            )
        ],
        metadata={"kernelspec": {"name": "python3", "display_name": "Python 3"}},
    )
    out.mkdir(parents=True, exist_ok=True)
    jupytext.write(index, out / "index.ipynb")
    (out / "README.md").write_text(
        "# colab branch\n\nGenerated by the `Build Colab notebooks` workflow from "
        "`main`. Don't edit it by hand: change the `.py` scripts on `main` instead.\n"
    )
    print(f"Built {len(links)} notebooks into {out}")


if __name__ == "__main__":
    main(sys.argv[1])
